class MyWorker extends Thread {
    public void run() {
        System.out.println("새로운 일꾼이 일을 시작합니다!");
    }
}

public class Main {
    public static void main(String[] args) {
        MyWorker worker = new MyWorker();
        worker.start(); // 일꾼에게 일을 시작하라고 지시합니다.

        System.out.println("메인 일꾼도 자기 일을 합니다.");
    }
}
